def worker_loop(agent, task_queue):
    while True:
        task = task_queue.get_next_compatible(agent.capabilities)
        if task:
            task_queue.mark_in_progress(task, agent)
            result = agent.execute(task)
            task_queue.mark_complete(task, result)
