def negotiate(buyer, seller, item, deadline):
    offer = seller.initial_offer(item)
    while not deadline.reached():
        if buyer.accepts(offer):
            return offer
        counter = buyer.counter(offer)
        if seller.accepts(counter):
            return counter
        offer = seller.counter(counter)
    return None  # failed
